def f(inp):
    import collections
    cnt=collections.Counter(v for row in inp for v in row)
    out=[row[:] for row in inp]
    # find closed frames
    for r in range(len(inp)):
        for c in range(len(inp[0])):
            if inp[r][c]==0: continue
            col=inp[r][c]; H,W=len(inp),len(inp[0])
            # bounding box of connected component of col including orthogonally/4-connected
            stack=[(r,c)]; seen={(r,c)}; comps=[]
            while stack:
                x,y=stack.pop(); comps.append((x,y)); 
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
