            rs=[p[0] for p in comps]; cs=[p[1] for p in comps]
            minR,maxR=min(rs),max(rs); minC,maxC=min(cs),max(cs)
            # check it forms a closed rectangular ring: every row minR..maxR has col at minC and maxC, similarly cols
            closed=True
            for rr in range(minR,maxR+1):
                if inp[rr][minC]!=col or inp[rr][maxC]!=col: closed=False
            for cc in range(minC,maxC+1):
                if inp[minR][cc]!=col or inp[maxR][cc]!=col: closed=False
            if closed and maxR-minR>=1 and maxC-minC>=1:
                fill=None
                for rr in range(minR+1,maxR):
                    for cc in range(minC+1,maxC):
                        if inp[rr][cc]==0: fill=cnt[col]-1
                if fill is not None:
                    for rr in range(minR+1,maxR):
                        for cc in range(minC+1,maxC):
                            out[rr][cc]=fill
    return out
