G=load()

def analyze(inp,out,name='demo'):
    H,W=len(inp),len(inp[0])
    # find connected components of each color (4-conn), keep only complete rings
    cnt=collections.Counter(v for row in inp for v in row)
    changes=collections.defaultdict(list)
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=out[r][c]: changes[inp[r][c]].append((r,c))
    result=[]
    seen=[[False]*W for _ in range(H)]
    for rr in range(H):
        for cc in range(W):
            if seen[rr][cc]: continue
            col=inp[rr][cc]; stack=[(rr,cc)]; seen[rr][cc]=True; cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy=x+dx,y+dy
                    if 0<=xx<H and 0<=yy<W and inp[xx][yy]==col and not seen[xx][yy]:
                        seen[xx][yy]=True; stack.append((xx,yy))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            mnR,mnC=min(rs),min(cs); mxR,mxC=max(rs),max(cs)
            # ring check: every boundary cell of bbox is col, and bbox area <= component (component == ring)
            is_ring=True
            for r in range(mnR,mxR+1):
                for c in range(mnC,mxC+1):
                    if inp[r][c]==col and not (r==mnR or r==mxR or c==mnC or c==mxC): is_ring=False
            if not is_ring: continue
            # interior zeros
            zeros=0
            for r in range(mnR+1,mxR):
                for c in range(mnC+1,mxC):
                    if inp[r][c]==0: zeros+=1
            if zeros==0: continue
            # what did interior become? take changed cells inside bbox
            new_vals=collections.Counter(out[r][c] for r in range(mnR+1,mxR) for c in range(mnC+1,mxC) if out[r][c]!=0 and out[r][c]!=inp[r][c])
            result.append({'name':name,'col':col,'bbox':(mnR,mnC,mxR,mxC),'size':(mxR-mnR)*(mxC-mnC),'interior_zeros':zeros,'fill':new_vals.most_common(1)[0][0]})
    return result

