def comps(inp,target=None, seen=None, colmap=None):
    H,W=len(inp),len(inp[0])
    res=[]
    for rr in range(H):
        for cc in range(W):
            v=inp[rr][cc]
            if colmap is not None and colmap[v] not in target: continue
            stack=[(rr,cc)]; seen[(rr,cc)]=(v,(rr,cc)); cells=[]
            while stack:
                _,p=stack.pop(); x,y=p
                cells.append(p)
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(x+dx,y+dy)
                    if 0<=q[0]<H and 0<=q[1]<W and not seen.get(q):
                        vv=inp[q[0]][q[1]]
                        if colmap is not None and colmap[vv] not in target: continue
                        seen[q]=(vv,q); stack.append(q)
            res.append(cells)
    return res

def rings(inp,out):
    H,W=len(inp),len(inp[0])
    R=[]
    # maximal same-color components -> check ring property
    seen=[[False]*W for _ in range(H)]
    def cell_seen(rr,cc): return seen[rr][cc]
    for col in set(v for row in inp for v in row):
        for rr in range(H):
            for cc in range(W):
                if cell_seen(rr,cc): continue
                stack=[(rr,cc)]; seen[rr][cc]=True; cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if 0<=q[0]<H and 0<=q[1]<W and inp[q[0]][q[1]]==col and not cell_seen(q[0],q[1]):
                            seen[q[0]][q[1]]=True; stack.append(q)
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                mnR,mnC=min(rs),min(cs); mxR,mxC=max(rs),max(cs)
                h=w_ = mxR-mnR,mxC-mnC
                ok=True
                for r in range(mnR,mxR+1):
                    if inp[r][mnC]!=col or inp[r][mxC]!=col: ok=False
                for c in range(mnC,mxC+1):
                    if inp[mnR][c]!=col or inp[mxR][c]!=col: ok=False
                if ok and h>=3 and w_>=3:
                    R.append((mnR,mnC,mxR,mxC,col,cells))
    return R

def inner_components(inp,mnR,mnC,mxR,mxC):
    # components fully contained in bbox interior, not touching border
    H,W=len(inp),len(inp[0])
    out=[]
    seen=[]
    for rr in range(mnR+1,mxR):
        for cc in range(mnC+1,mxC):
            v=inp[rr][cc]
            if v==0: continue
            key=((v,rr,cc))
            if any(key==k for k in seen): continue
            stack=[(rr,cc)]; seen.append(key); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(x+dx,y+dy)
                    if 0<=q[0]<=mxR and 0<=q[1]<=mxC and mnR<q[0]<mxR and mnC<q[1]<mxC:
                        if v==inp[q[0]][q[1]]:
                            if (inp[q[0]][q[1]],q[0],q[1]) not in seen:
                                seen.append((inp[q[0]][q[1]],q[0],q[1])); stack.append(q)
            out.append(cells)
    return out

