    res=[]; seen=[[False]*W for _ in range(H)]
    for rr in range(H):
        for cc in range(W):
            if seen[rr][cc]: continue
            col=inp[rr][cc]
            stack=[(rr,cc)]; seen[rr][cc]=True; cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(x+dx,y+dy)
                    if 0<=q[0]<H and 0<=q[1]<W and inp[q[0]][q[1]]==col and not seen[q[0]][q[1]]:
                        seen[q[0]][q[1]]=True; stack.append(q)
